using System;
using System.Linq;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshAncientBossSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('prior',@prior::json,'summons',(SELECT json_agg(s ORDER BY id) FROM revora_ancient_summons s WHERE uid=@uid),'offerings',(SELECT json_agg(o ORDER BY item_uid) FROM revora_ancient_offerings o JOIN revora_ancient_summons s ON s.id=o.summon WHERE s.uid=@uid),'battles',(SELECT json_agg(b ORDER BY summon) FROM revora_ancient_battles b JOIN revora_ancient_summons s ON s.id=b.summon WHERE s.uid=@uid),'kills',(SELECT json_agg(k ORDER BY summon,slot) FROM revora_ancient_battle_kills k JOIN revora_ancient_summons s ON s.id=k.summon WHERE s.uid=@uid),'victories',(SELECT json_agg(v ORDER BY summon) FROM revora_ancient_victories v JOIN revora_ancient_summons s ON s.id=v.summon WHERE s.uid=@uid))::text","prior",FreshAmuletsSnapshot(p),"uid",(long)p.Entity.UID));}
    static void FreshAncientBossSave(GameState p,string stage,int kills,int hits){Require(EntityTable.SaveEntity(p));Sql("UPDATE revora_fresh_ancient_boss_probe SET stage=@stage,kills=@kills,hits=@hits,snapshot=@snapshot","stage",stage,"kills",kills,"hits",hits,"snapshot",FreshAncientBossSnapshot(p));}
    static void FreshAncientBossProcess(string phase){
        var p=FreshLoadSaved(true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);Require(!p.Fake && p.Account.State==AccountTable.AccountState.Player && !PirateFenced(p));
        if((bool)Sql("SELECT to_regclass('revora_fresh_ancient_boss_probe') IS NULL")){
            Require(phase.EndsWith("win") && FreshAmuletsSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_amulets_probe")) && (long)Sql("SELECT count(*) FROM revora_ancient_summons WHERE uid=@uid","uid",(long)p.Entity.UID)==0);Sql("CREATE TABLE revora_fresh_ancient_boss_probe(stage text,kills integer,hits integer,snapshot text);INSERT INTO revora_fresh_ancient_boss_probe VALUES('new',0,0,@snapshot)","snapshot",FreshAncientBossSnapshot(p));
        }
        string saved=Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_ancient_boss_probe")),current=FreshAncientBossSnapshot(p);
        if(saved!=current){
            Require(phase.EndsWith("claim") && Convert.ToString(Sql("SELECT stage FROM revora_fresh_ancient_boss_probe"))=="victory" && (bool)Sql("SELECT jsonb_array_length(@old::jsonb->'battles')=1 AND jsonb_array_length(@now::jsonb->'battles')=1 AND (@old::jsonb#>>'{battles,0,defeated}')='31' AND (@old::jsonb#>>'{battles,0,generation}')<>(@now::jsonb#>>'{battles,0,generation}') AND (@old::jsonb #- '{battles,0,generation}')=(@now::jsonb #- '{battles,0,generation}')","old",saved,"now",current));
            // Startup revokes the old actor generation, retaining the earned victory and every other field.
            Sql("UPDATE revora_fresh_ancient_boss_probe SET snapshot=@snapshot WHERE stage='victory'","snapshot",current);System.Console.WriteLine("[fresh-ancient-boss] verified generation-only cold recovery");
        }
        Require(FreshAncientBossSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_ancient_boss_probe")));string stage=Convert.ToString(Sql("SELECT stage FROM revora_fresh_ancient_boss_probe"));int kills=Convert.ToInt32(Sql("SELECT kills FROM revora_fresh_ancient_boss_probe")),hits=Convert.ToInt32(Sql("SELECT hits FROM revora_fresh_ancient_boss_probe"));
        if(phase.EndsWith("win")){
            Require(stage=="new");HeartTalk(p,300017,0);string before=FreshAncientBossSnapshot(p);HeartTalk(p,300017,3);Require(before==FreshAncientBossSnapshot(p));var prior=p.Inventory.Objects.Select(i=>i.UID).ToArray();HeartTalk(p,300017,0);HeartTalk(p,300017,1);Require(p.Entity.MapID>=11000 && p.Inventory.Count==prior.Length-9 && (long)Sql("SELECT count(*) FROM revora_ancient_offerings o JOIN revora_ancient_summons s ON s.id=o.summon WHERE s.uid=@uid","uid",(long)p.Entity.UID)==9);
            Require((long)Sql("SELECT count(*) FROM items WHERE entityid=@uid AND uid=ANY(@prior)","uid",(long)p.Entity.UID,"prior",prior.Select(u=>(long)u).ToArray())==prior.Length-9);foreach(uint family in new uint[]{9916601,9916602,9916603,9916604,9916605})FreshClassicKill(p,p.Entity.MapID,family,ref kills,ref hits);Call(Feature("AncientDevilQuest"),"Tick");Require(p.Entity.MapID==1052 && (long)Sql("SELECT count(*) FROM revora_ancient_summons WHERE uid=@uid AND state='victory' AND valuable_reward","uid",(long)p.Entity.UID)==1 && (long)Sql("SELECT count(*) FROM revora_ancient_victories v JOIN revora_ancient_summons s ON s.id=v.summon WHERE s.uid=@uid AND claimed_at IS NULL AND cardinality(claimed_items)=0","uid",(long)p.Entity.UID)==1);FreshAncientBossSave(p,"victory",kills,hits);
        }else if(phase.EndsWith("claim")){
            Require(stage=="victory");uint type=Convert.ToUInt32(Sql("SELECT item_type FROM revora_ancient_victories v JOIN revora_ancient_summons s ON s.id=v.summon WHERE s.uid=@uid","uid",(long)p.Entity.UID));int count=Convert.ToInt32(Sql("SELECT quantity FROM revora_ancient_victories v JOIN revora_ancient_summons s ON s.id=v.summon WHERE s.uid=@uid","uid",(long)p.Entity.UID));var prior=p.Inventory.Objects.Select(i=>i.UID).ToArray();HeartTalk(p,300017,0);HeartTalk(p,300017,3);var added=p.Inventory.Objects.Where(i=>!prior.Contains(i.UID)).ToArray();Require(added.Length==count+1 && added.Count(i=>i.ID==type && !i.Bound)==count && added.Count(i=>i.Bound && ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7)==1 && prior.All(uid=>p.Inventory.ContainsUID(uid)));FreshAncientBossSave(p,"claimed",kills,hits);System.Console.WriteLine("[fresh-ancient-boss] reward="+type+" count="+count+" bound-p7=1");
        }else Require(phase.EndsWith("reload") && stage=="claimed");
        if(!phase.EndsWith("win")){
            Require((long)Sql("SELECT count(*) FROM revora_ancient_summons WHERE uid=@uid AND state='claimed'","uid",(long)p.Entity.UID)==1);string exact=FreshAncientBossSnapshot(p);HeartTalk(p,300017,0);HeartTalk(p,300017,3);HeartTalk(p,300017,1);Require(exact==FreshAncientBossSnapshot(p));
        }
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11020 AND source='ancient-collection-v1'","uid",(long)p.Entity.UID)==1 && (long)Sql("SELECT count(*) FROM revora_ancient_battle_kills k JOIN revora_ancient_summons s ON s.id=k.summon WHERE s.uid=@uid","uid",(long)p.Entity.UID)==5 && FreshAncientBossSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_ancient_boss_probe")) && !PirateFenced(p));System.Console.WriteLine("[career-process] "+phase+"-passed kills="+kills+" hits="+hits+" bag="+p.Inventory.Count);Server.CommandsAI("@close");throw new InvalidOperationException("Fresh Ancient boss did not close.");
    }
}
